"use client";

import { api } from "@/lib/api";
import { useFixedIdempotencyKey } from "@/lib/idempotency";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { Suspense, useEffect, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Spinner } from "@/components/ui/spinner";

function VerifyEmailContent() {
  const searchParams = useSearchParams();
  const token = searchParams.get("token");
  const [status, setStatus] = useState<"loading" | "success" | "error">(
    "loading"
  );
  const [message, setMessage] = useState("");
  // One key for the whole page, not one per attempt. This effect fires on mount, and React
  // invokes mount effects twice in dev StrictMode; without a shared key that is two
  // verifications of the same single-use token.
  const idempotencyKey = useFixedIdempotencyKey();

  useEffect(() => {
    if (!token) {
      setStatus("error");
      setMessage("No verification token provided.");
      return;
    }

    api("/verify-email", {
      method: "POST",
      body: JSON.stringify({ token }),
      idempotencyKey,
    })
      .then(() => {
        setStatus("success");
        setMessage("Email verified successfully!");
        toast.success("Email verified successfully!");
      })
      .catch((err: any) => {
        setStatus("error");
        const text = err.message || "Verification failed.";
        setMessage(text);
        toast.error(text);
      });
  }, [token, idempotencyKey]);

  return (
    <Card className="w-full max-w-sm">
      {status === "loading" && (
        <CardContent className="flex flex-col items-center gap-4 text-center">
          <Spinner className="size-6" />
          <p>Verifying your email...</p>
        </CardContent>
      )}

      {status === "success" && (
        <>
          <CardHeader>
            <CardTitle className="text-emerald-600 dark:text-emerald-400">
              Verified!
            </CardTitle>
          </CardHeader>
          <CardContent className="flex flex-col items-center gap-4 text-center">
            <p>{message}</p>
            <Button asChild>
              <Link href="/login">Log In</Link>
            </Button>
          </CardContent>
        </>
      )}

      {status === "error" && (
        <>
          <CardHeader>
            <CardTitle className="text-destructive">Verification Failed</CardTitle>
          </CardHeader>
          <CardContent className="flex flex-col items-center gap-4 text-center">
            <p>{message}</p>
            <Button asChild>
              <Link href="/login">Back to Login</Link>
            </Button>
          </CardContent>
        </>
      )}
    </Card>
  );
}

export default function VerifyEmailPage() {
  return (
    <div className="flex min-h-screen items-center justify-center">
      <Suspense fallback={<Spinner className="size-6" />}>
        <VerifyEmailContent />
      </Suspense>
    </div>
  );
}
